-- pemdb1.V_CB_MTSO source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CB_MTSO` (`MTSO_ID`,
`MTSO_NAME`) AS
select
    `pemdb1`.`CB_MTSO`.`MTSO_ID` AS `mtso_id`,
    if((`pemdb1`.`CB_MTSO`.`MTSO_NAME` = 'ITC'), '???', `pemdb1`.`CB_MTSO`.`MTSO_NAME`) AS `mtso_name`
from
    `pemdb1`.`CB_MTSO`;


-- pemdb1.V_CL_CELL_MAP_CO source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_CELL_MAP_CO` (`C_UID`,
`MME_GRP_ID`,
`ENB_ID`,
`CELL_ID`,
`CELLNUM`,
`SECTOR`,
`FA`,
`PCI`,
`EMS_ID`,
`FREQUENCY`,
`VENDOR_ID`,
`ADM_STATE`,
`CA_PAIR_CNUM1`,
`CA_PAIR_CNUM2`,
`CA_PAIR_CNUM1_FREQ`,
`CA_PAIR_CNUM2_FREQ`,
`PLMN`,
`CO_YN`) AS
select
    `A`.`C_UID` AS `C_UID`,
    `A`.`MME_GRP_ID` AS `MME_GRP_ID`,
    `A`.`ENB_ID` AS `ENB_ID`,
    `A`.`CELL_ID` AS `CELL_ID`,
    `A`.`CELLNUM` AS `CELLNUM`,
    0 AS `SECTOR`,
    0 AS `FA`,
    `A`.`PCI` AS `PCI`,
    '' AS `EMS_ID`,
    `A`.`FREQUENCY` AS `FREQUENCY`,
    0 AS `VENDOR_ID`,
    0 AS `ADM_STATE`,
    0 AS `CA_PAIR_CNUM1`,
    0 AS `CA_PAIR_CNUM2`,
    '' AS `CA_PAIR_CNUM1_FREQ`,
    '' AS `CA_PAIR_CNUM2_FREQ`,
    `A`.`PLMN` AS `PLMN`,
    'Y' AS `CO_YN`
from
    `pemdb1`.`CL_CELL_MAP_CO` `A`
where
    (`A`.`PLMN` <> '45005')
union all
select
    `A`.`C_UID` AS `C_UID`,
    `A`.`MME_GRP_ID` AS `MME_GRP_ID`,
    `A`.`ENB_ID` AS `ENB_ID`,
    `A`.`CELL_ID` AS `CELL_ID`,
    `A`.`CELLNUM` AS `CELLNUM`,
    `A`.`SECTOR` AS `SECTOR`,
    `A`.`FA` AS `FA`,
    `A`.`PCI` AS `PCI`,
    `A`.`EMS_ID` AS `EMS_ID`,
    `A`.`FREQUENCY` AS `FREQUENCY`,
    `A`.`VENDOR_ID` AS `VENDOR_ID`,
    `A`.`ADM_STATE` AS `ADM_STATE`,
    `A`.`CA_PAIR_CNUM1` AS `CA_PAIR_CNUM1`,
    `A`.`CA_PAIR_CNUM2` AS `CA_PAIR_CNUM2`,
    `A`.`CA_PAIR_CNUM1_FREQ` AS `CA_PAIR_CNUM1_FREQ`,
    `A`.`CA_PAIR_CNUM2_FREQ` AS `CA_PAIR_CNUM2_FREQ`,
    '45005' AS `PLMN`,
    (case
        when ((`A`.`ENB_ID` = `B`.`enb_id`)
            and (`A`.`CELLNUM` = `B`.`cellnum`)) then 'Y'
        else 'N'
    end) AS `CO_YN`
from
    (`pemdb1`.`CL_CELL_MAP` `A`
left join (
    select
        distinct `pemdb1`.`CL_CELL_MAP_CO`.`C_UID` AS `c_uid`,
        `pemdb1`.`CL_CELL_MAP_CO`.`MME_GRP_ID` AS `mme_grp_id`,
        `pemdb1`.`CL_CELL_MAP_CO`.`ENB_ID` AS `enb_id`,
        `pemdb1`.`CL_CELL_MAP_CO`.`CELL_ID` AS `cell_id`,
        `pemdb1`.`CL_CELL_MAP_CO`.`CELLNUM` AS `cellnum`,
        `pemdb1`.`CL_CELL_MAP_CO`.`PCI` AS `pci`,
        `pemdb1`.`CL_CELL_MAP_CO`.`FREQUENCY` AS `frequency`,
        `pemdb1`.`CL_CELL_MAP_CO`.`TAC` AS `tac`,
        `pemdb1`.`CL_CELL_MAP_CO`.`PLMN` AS `plmn`
    from
        `pemdb1`.`CL_CELL_MAP_CO`
    where
        (`pemdb1`.`CL_CELL_MAP_CO`.`PLMN` = '45005')) `B` on
    (((`A`.`ENB_ID` = `B`.`enb_id`) and (`A`.`CELLNUM` = `B`.`cellnum`))));


-- pemdb1.V_CL_ENB source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_ENB` (`C_UID`,
`OPR_STATUS`,
`ENB_ID`,
`MASTER_IP`,
`MASTER_IP_2`,
`MASTER_IP_3`,
`MASTER_IP_4`,
`EMS_ID`,
