`PART_ID`,
`PART_NAME`,
`MTSO_TEAM_ID`,
`MTSO_TEAM_NAME`,
`COMPANY_ID`,
`REGION_ID`,
`VENDOR_ID`,
`VENDOR`,
`POST1`,
`POST2`,
`CITY`,
`GU`,
`DONG`,
`BUNGI`,
`LATITUDE`,
`LONGITUDE`,
`LATITUDE_NORM`,
`LONGITUDE_NORM`,
`SWITCH_INFO`,
`IMPORTANT_FLAG`,
`CA_TYPE`,
`MC_TYPE`,
`WIDE_BAND`,
`UPDATE_DATE`,
`MME_GRP_ID`) AS
select
    `a`.`C_UID` AS `c_uid`,
    `a`.`OPR_STATUS` AS `opr_status`,
    `a`.`ENB_ID` AS `enb_id`,
    `a`.`MASTER_IP` AS `master_ip`,
    `a`.`MASTER_IP_2` AS `master_ip_2`,
    `a`.`MASTER_IP_3` AS `master_ip_3`,
    `a`.`MASTER_IP_4` AS `master_ip_4`,
    `a`.`EMS_ID` AS `ems_id`,
    `a`.`BTS_NAME` AS `bts_name`,
    `pemdb1`.`b`.`MTSO_ID` AS `mtso_id`,
    `a`.`MTSO_NAME` AS `mtso_name`,
    if((regexp_substr(`a`.`VLAN_INFO`, '[0-9]{4}') is null), `a`.`VLAN_INFO`, regexp_substr(`a`.`VLAN_INFO`, '[0-9]{4}|')) AS `vlan_id`,
    ((0 <> `pemdb1`.`b`.`MTSO_ID`)
    or (0 <> '_')
    or (0 <> if((regexp_substr(`a`.`VLAN_INFO`, '[0-9]{4}') is null), `a`.`VLAN_INFO`, regexp_substr(`a`.`VLAN_INFO`, '[0-9]{4}|')))) AS `vlan_info`,
    `a`.`BRANCH_ID` AS `branch_id`,
    `a`.`BRANCH_NAME` AS `branch_name`,
    `a`.`OPTEAM_ID` AS `opteam_id`,
    `a`.`OPTEAM_NAME` AS `opteam_name`,
    `a`.`PART_ID` AS `part_id`,
    `a`.`PART_NAME` AS `part_name`,
    `a`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `a`.`MTSO_TEAM_NAME` AS `mtso_team_name`,
    `a`.`COMPANY_ID` AS `company_id`,
    `a`.`REGION_ID` AS `region_id`,
    `a`.`VENDOR_ID` AS `vendor_id`,
    '' AS `vendor`,
    `a`.`POST1` AS `post1`,
    `a`.`POST2` AS `post2`,
    `a`.`CITY` AS `city`,
    `a`.`GU` AS `gu`,
    `a`.`DONG` AS `dong`,
    `a`.`BUNGI` AS `bungi`,
    `a`.`LATITUDE` AS `latitude`,
    `a`.`LONGITUDE` AS `longitude`,
    `a`.`LATITUDE_NORM` AS `latitude_norm`,
    `a`.`LONGITUDE_NORM` AS `longitude_norm`,
    `a`.`SWITCH_INFO` AS `switch_info`,
    `c`.`IMPORTANT_FLAG` AS `important_flag`,
    `a`.`CA_TYPE` AS `ca_type`,
    `a`.`MC_TYPE` AS `mc_type`,
    `a`.`WIDE_BAND` AS `wide_band`,
    `a`.`UPDATE_DATE` AS `update_date`,
    `a`.`MME_GRP_ID` AS `MME_GRP_ID`
from
    ((`pemdb1`.`CL_ENB` `a`
left join `pemdb1`.`V_CB_MTSO` `b` on
    ((`a`.`MTSO_NAME` = `pemdb1`.`b`.`MTSO_NAME`)))
left join `pemdb1`.`CL_ENB_IMPORTANT` `c` on
    ((`a`.`C_UID` = `c`.`C_UID`)));


-- pemdb1.V_CL_ENB_ENC_CO source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_ENB_ENC_CO` (`C_UID`,
`OPR_STATUS`,
`ENB_ID`,
`DECODE`,
`MASTER_IP`,
`MASTER_IP_2`,
`MASTER_IP_3`,
`MASTER_IP_4`,
`EMS_ID`,
`BTS_NAME`,
`MTSO_NAME`,
`VLAN_INFO`,
`BRANCH_ID`,
`BRANCH_NAME`,
`OPTEAM_ID`,
`OPTEAM_NAME`,
`PART_ID`,
`PART_NAME`,
`MTSO_TEAM_ID`,
`MTSO_TEAM_NAME`,
`COMPANY_ID`,
`REGION_ID`,
`VENDOR_ID`,
`VENDOR`,
`POST1`,
`POST2`,
`CITY`,
`GU`,
`DONG`,
`BUNGI`,
`BUNGI1`,
`BUNGI2`,
`BUNGI3`,
`LATITUDE`,
`LONGITUDE`,
`LATITUDE_NORM`,
`LONGITUDE_NORM`,
`SWITCH_INFO`,
`CA_TYPE`,
`MC_TYPE`,
`WIDE_BAND`,
`UPDATE_DATE`,
`MME_GRP_ID`,
`PLMN`,
`CO_YN`) AS
select
    `A`.`C_UID` AS `c_uid`,
    `A`.`OPR_STATUS` AS `opr_status`,
    `A`.`ENB_ID` AS `enb_id`,
    `A`.`DECODE` AS `DECODE`,
    `A`.`MASTER_IP` AS `master_ip`,
    `A`.`MASTER_IP_2` AS `master_ip_2`,
    `A`.`MASTER_IP_3` AS `master_ip_3`,
    `A`.`MASTER_IP_4` AS `master_ip_4`,
    '' AS `ems_id`,
    `A`.`BTS_NAME` AS `bts_name`,
    `A`.`MTSO_NAME` AS `mtso_name`,
    '' AS `vlan_info`,
    `A`.`BRANCH_ID` AS `branch_id`,
    `A`.`BRANCH_NAME` AS `branch_name`,
    `A`.`OPTEAM_ID` AS `opteam_id`,
    `A`.`OPTEAM_NAME` AS `opteam_name`,
    `A`.`PART_ID` AS `part_id`,
    `A`.`PART_NAME` AS `part_name`,
    0 AS `mtso_team_id`,
    `A`.`MTSO_NAME` AS `mtso_team_name`,
    `A`.`COMPANY_ID` AS `company_id`,
    0 AS `region_id`,
    cast(`A`.`VENDOR_ID` as unsigned) AS `CAST(A.vendor_id AS UNSIGNED)`,
    `A`.`VENDOR_NAME` AS `vendor`,
    `A`.`POST1` AS `post1`,
    `A`.`POST2` AS `post2`,
    `A`.`CITY` AS `city`,
    `A`.`GU` AS `gu`,
    `A`.`DONG` AS `dong`,
    `A`.`BUNGI` AS `bungi`,
    '' AS `bungi1`,
    '' AS `bungi2`,
    '' AS `bungi3`,
    `A`.`LATITUDE` AS `latitude`,
    `A`.`LONGITUDE` AS `longitude`,
    `A`.`LATITUDE_NORM` AS `latitude_norm`,
    `A`.`LONGITUDE_NORM` AS `longitude_norm`,
    '' AS `switch_info`,
    '' AS `ca_type`,
    '' AS `mc_type`,
    '' AS `wide_band`,
    `A`.`UPDATE_DATE` AS `update_date`,
    `A`.`MME_GRP_ID` AS `MME_GRP_ID`,
    `A`.`PLMN` AS `PLMN`,
    'Y' AS `CO_YN`
from
    `pemdb1`.`CL_ENB_ENC_CO` `A`
where
    (`A`.`PLMN` <> '45005')
union all
select
    `A`.`C_UID` AS `c_uid`,
    `A`.`OPR_STATUS` AS `opr_status`,
    `A`.`ENB_ID` AS `enb_id`,
    `A`.`DECODE` AS `DECODE`,
    `A`.`MASTER_IP` AS `master_ip`,
    `A`.`MASTER_IP_2` AS `master_ip_2`,
    `A`.`MASTER_IP_3` AS `master_ip_3`,
    `A`.`MASTER_IP_4` AS `master_ip_4`,
    `A`.`EMS_ID` AS `ems_id`,
    `A`.`BTS_NAME` AS `bts_name`,
    `A`.`MTSO_NAME` AS `mtso_name`,
    `A`.`VLAN_INFO` AS `vlan_info`,
    `A`.`BRANCH_ID` AS `branch_id`,
    `A`.`BRANCH_NAME` AS `branch_name`,
    `A`.`OPTEAM_ID` AS `opteam_id`,
    `A`.`OPTEAM_NAME` AS `opteam_name`,
    `A`.`PART_ID` AS `part_id`,
    `A`.`PART_NAME` AS `part_name`,
    `A`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `A`.`MTSO_TEAM_NAME` AS `mtso_team_name`,
    `A`.`COMPANY_ID` AS `company_id`,
    `A`.`REGION_ID` AS `region_id`,
    `A`.`VENDOR_ID` AS `vendor_id`,
    '' AS `vendor`,
    `A`.`POST1` AS `post1`,
    `A`.`POST2` AS `post2`,
    `A`.`CITY` AS `city`,
    `A`.`GU` AS `gu`,
    `A`.`DONG` AS `dong`,
    `A`.`BUNGI` AS `bungi`,
    `A`.`BUNGI1` AS `bungi1`,
    `A`.`BUNGI2` AS `bungi2`,
    `A`.`BUNGI3` AS `bungi3`,
    `A`.`LATITUDE` AS `latitude`,
    `A`.`LONGITUDE` AS `longitude`,
    `A`.`LATITUDE_NORM` AS `latitude_norm`,
    `A`.`LONGITUDE_NORM` AS `longitude_norm`,
    `A`.`SWITCH_INFO` AS `switch_info`,
    `A`.`CA_TYPE` AS `ca_type`,
    `A`.`MC_TYPE` AS `mc_type`,
    `A`.`WIDE_BAND` AS `wide_band`,
    `A`.`UPDATE_DATE` AS `update_date`,
    `A`.`MME_GRP_ID` AS `MME_GRP_ID`,
    '45005' AS `PLMN`,
    (case
        when (`A`.`DECODE` = `B`.`DECODE`) then 'Y'
        else 'N'
    end) AS `CO_YN`
from
    (`pemdb1`.`CL_ENB_ENC` `A`
left join (
    select
        `pemdb1`.`CL_ENB_ENC_CO`.`OPR_STATUS` AS `OPR_STATUS`,
        `pemdb1`.`CL_ENB_ENC_CO`.`C_UID` AS `C_UID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MME_GRP_ID` AS `MME_GRP_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`ENB_ID` AS `ENB_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BTS_NAME` AS `BTS_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`SISUL_CODE` AS `SISUL_CODE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`VENDOR_ID` AS `VENDOR_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`VENDOR_NAME` AS `VENDOR_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BRANCH_ID` AS `BRANCH_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BRANCH_NAME` AS `BRANCH_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`OPTEAM_ID` AS `OPTEAM_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`OPTEAM_NAME` AS `OPTEAM_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`COMPANY_ID` AS `COMPANY_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`PART_ID` AS `PART_ID`,
        `pemdb1`.`CL_ENB_ENC_CO`.`PART_NAME` AS `PART_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`INSTALL_DATE` AS `INSTALL_DATE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`UPDATE_DATE` AS `UPDATE_DATE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BTS_TYPE` AS `BTS_TYPE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BTS_FORMAT` AS `BTS_FORMAT`,
        `pemdb1`.`CL_ENB_ENC_CO`.`POST1` AS `POST1`,
        `pemdb1`.`CL_ENB_ENC_CO`.`POST2` AS `POST2`,
        `pemdb1`.`CL_ENB_ENC_CO`.`CITY` AS `CITY`,
        `pemdb1`.`CL_ENB_ENC_CO`.`GU` AS `GU`,
        `pemdb1`.`CL_ENB_ENC_CO`.`DONG` AS `DONG`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BUNGI` AS `BUNGI`,
        `pemdb1`.`CL_ENB_ENC_CO`.`LATITUDE` AS `LATITUDE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`LONGITUDE` AS `LONGITUDE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`LATITUDE_NORM` AS `LATITUDE_NORM`,
        `pemdb1`.`CL_ENB_ENC_CO`.`LONGITUDE_NORM` AS `LONGITUDE_NORM`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MZCOMPANY` AS `MZCOMPANY`,
        `pemdb1`.`CL_ENB_ENC_CO`.`ENB_GROUP` AS `ENB_GROUP`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MTSO_NAME` AS `MTSO_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`SERIALNUMBER` AS `SERIALNUMBER`,
        `pemdb1`.`CL_ENB_ENC_CO`.`GY_TYPE` AS `GY_TYPE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`GY_SISUL_CODE` AS `GY_SISUL_CODE`,
        `pemdb1`.`CL_ENB_ENC_CO`.`GY_NAME` AS `GY_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`ROAD_NAME` AS `ROAD_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BD_MAIN_NUM` AS `BD_MAIN_NUM`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BD_SUB_NUM` AS `BD_SUB_NUM`,
        `pemdb1`.`CL_ENB_ENC_CO`.`BD_NAME` AS `BD_NAME`,
        `pemdb1`.`CL_ENB_ENC_CO`.`ROAD_DONG` AS `ROAD_DONG`,
        `pemdb1`.`CL_ENB_ENC_CO`.`ROAD_LAW_RI` AS `ROAD_LAW_RI`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MASTER_IP` AS `MASTER_IP`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MASTER_IP_2` AS `MASTER_IP_2`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MASTER_IP_3` AS `MASTER_IP_3`,
        `pemdb1`.`CL_ENB_ENC_CO`.`MASTER_IP_4` AS `MASTER_IP_4`,
        `pemdb1`.`CL_ENB_ENC_CO`.`TAC` AS `TAC`,
        `pemdb1`.`CL_ENB_ENC_CO`.`PLMN` AS `PLMN`,
        `pemdb1`.`CL_ENB_ENC_CO`.`DECODE` AS `DECODE`
    from
        `pemdb1`.`CL_ENB_ENC_CO`
    where
        (`pemdb1`.`CL_ENB_ENC_CO`.`PLMN` = '45005')) `B` on
    ((`A`.`DECODE` = `B`.`DECODE`)));


-- pemdb1.V_CL_EPC source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_EPC` (`EQUIP_TYPE`,
`EQUIP_ID`,
`EQUIP_NAME`,
`EQUIP_GRP_ID`,
`BRANCH_ID`,
`BRANCH_NAME`,
`MTSO_TEAM_ID`,
`TEAM_NAME`,
`VENDOR_ID`) AS with `EQUIP_INF` as (
select
    'MME' AS `equip_type`,
    `a`.`MME_ID` AS `equip_id`,
    ((0 <> 'MME#')
    or (0 <> `a`.`MME_ID`)) AS `equip_name`,
    `a`.`MME_GRP_ID` AS `equip_grp_id`,
    `a`.`BRANCH_ID` AS `branch_id`,
    `b`.`BRANCH_NAME` AS `branch_name`,
    `a`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `c`.`TEAM_NAME` AS `team_name`,
    `a`.`VENDOR_ID` AS `vendor_id`
from
    ((`pemdb1`.`CL_MME` `a`
join `pemdb1`.`CM_BRANCH` `b`)
join `pemdb1`.`CM_TEAM` `c`)
where
    ((`a`.`OPR_STATUS` = 'ACT')
        and (`a`.`BRANCH_ID` = `b`.`BRANCH_ID`)
            and (`a`.`MTSO_TEAM_ID` = `c`.`TEAM_ID`))
union all
select
    'SGW' AS `equip_type`,
    `a`.`SGW_ID` AS `equip_id`,
    ((0 <> 'SGW#')
        or (0 <> `a`.`SGW_ID`)) AS `equip_name`,
    '0' AS `equip_grp_id`,
    `a`.`BRANCH_ID` AS `branch_id`,
    `b`.`BRANCH_NAME` AS `branch_name`,
    `a`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `c`.`TEAM_NAME` AS `team_name`,
    `a`.`VENDOR_ID` AS `vendor_id`
from
    ((`pemdb1`.`CL_SGW` `a`
join `pemdb1`.`CM_BRANCH` `b`)
join `pemdb1`.`CM_TEAM` `c`)
where
    ((`a`.`OPR_STATUS` = 'ACT')
        and (`a`.`BRANCH_ID` = `b`.`BRANCH_ID`)
            and (`a`.`MTSO_TEAM_ID` = `c`.`TEAM_ID`))
union all
select
    'PGW' AS `equip_type`,
    `a`.`PGW_ID` AS `equip_id`,
    ((0 <> 'PGW#')
        or (0 <> `a`.`PGW_ID`)) AS `equip_name`,
    '0' AS `equip_grp_id`,
    `a`.`BRANCH_ID` AS `branch_id`,
    `b`.`BRANCH_NAME` AS `branch_name`,
    `a`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `c`.`TEAM_NAME` AS `team_name`,
    `a`.`VENDOR_ID` AS `vendor_id`
from
    ((`pemdb1`.`CL_PGW` `a`
join `pemdb1`.`CM_BRANCH` `b`)
join `pemdb1`.`CM_TEAM` `c`)
where
    ((`a`.`OPR_STATUS` = 'ACT')
        and (`a`.`BRANCH_ID` = `b`.`BRANCH_ID`)
            and (`a`.`MTSO_TEAM_ID` = `c`.`TEAM_ID`))
union all
select
    'HLRCS' AS `equip_type`,
    `a`.`HLRCS_ID` AS `equip_id`,
    ((0 <> 'HLRCS#')
        or (0 <> `a`.`HLRCS_ID`)) AS `equip_name`,
    `a`.`HLR_GROUP_ID` AS `equip_grp_id`,
    `a`.`BRANCH_ID` AS `branch_id`,
    `b`.`BRANCH_NAME` AS `branch_name`,
    `a`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `c`.`TEAM_NAME` AS `team_name`,
    `a`.`VENDOR_ID` AS `vendor_id`
from
    ((`pemdb1`.`CL_HLRCS` `a`
join `pemdb1`.`CM_BRANCH` `b`)
join `pemdb1`.`CM_TEAM` `c`)
where
    ((`a`.`OPR_STATUS` = 'ACT')
        and (`a`.`BRANCH_ID` = `b`.`BRANCH_ID`)
            and (`a`.`MTSO_TEAM_ID` = `c`.`TEAM_ID`))
union all
select
    'IWF' AS `equip_type`,
    lpad(`a`.`IWF_ID`, 4, '0') AS `equip_id`,
    ((0 <> 'IWF#')
        or (0 <> lpad(`a`.`IWF_ID`, 4, '0'))) AS `equip_name`,
    '0' AS `equip_grp_id`,
    `a`.`BRANCH_ID` AS `branch_id`,
    `b`.`BRANCH_NAME` AS `branch_name`,
    `a`.`MTSO_TEAM_ID` AS `mtso_team_id`,
    `c`.`TEAM_NAME` AS `team_name`,
    `a`.`VENDOR_ID` AS `vendor_id`
from
    ((`pemdb1`.`CL_IWF` `a`
join `pemdb1`.`CM_BRANCH` `b`)
join `pemdb1`.`CM_TEAM` `c`)
where
    ((`a`.`OPR_STATUS` = 'ACT')
        and (`a`.`BRANCH_ID` = `b`.`BRANCH_ID`)
            and (`a`.`MTSO_TEAM_ID` = `c`.`TEAM_ID`)))
select
    `EQUIP_INF`.`equip_type` AS `EQUIP_TYPE`,
    `EQUIP_INF`.`equip_id` AS `EQUIP_ID`,
    `EQUIP_INF`.`equip_name` AS `EQUIP_NAME`,
    `EQUIP_INF`.`equip_grp_id` AS `EQUIP_GRP_ID`,
    `EQUIP_INF`.`branch_id` AS `BRANCH_ID`,
    `EQUIP_INF`.`branch_name` AS `BRANCH_NAME`,
    `EQUIP_INF`.`mtso_team_id` AS `MTSO_TEAM_ID`,
    `EQUIP_INF`.`team_name` AS `TEAM_NAME`,
    `EQUIP_INF`.`vendor_id` AS `VENDOR_ID`
from
    `EQUIP_INF`
order by
    `EQUIP_INF`.`equip_type`,
    `EQUIP_INF`.`equip_id`;


-- pemdb1.V_CL_MME source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_MME` (`MME_ID`,
`OPR_STATUS`,
`MME_GRP_ID`,
`BRANCH_ID`,
`LAREA_ID`,
`MTSO_ID`,
`MTSO_TEAM_ID`,
`VENDOR_ID`,
`MME_NAME`,
`NET_NAME`,
`HOST`,
`REALM`,
`DFTAPNV4`,
`DFTAPNV6`,
`DFTAPNV4V6`,
`N3_CNT`,
`DWRRETRY`,
`IWSRETRY`,
`CGCHKTM`,
`CAPA`,
`FEATLIST`,
`DFTRFSP`,
`DSCP`,
`USEIMEI`,
`PAGEFAIL`,
`RLB`,
`SDBCLR`,
`SESSCLR`,
`GTPCCLR`,
`VERSION`,
`INSTALL_DATE`,
`SERVICE_AREA`,
`UPDATE_DATETIME`,
`UPDATE_USER_ID`,
`INSERT_DATE`,
`UPDATE_DATE`,
`OFF_DATE`,
`EMS_ID`,
`MME_CODE`,
`SUB_GRP_NAME`) AS
select
    `pemdb1`.`CL_MME_ADV_TPL`.`MME_ID` AS `MME_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`OPR_STATUS` AS `OPR_STATUS`,
    `pemdb1`.`CL_MME_ADV_TPL`.`MME_GRP_ID` AS `MME_GRP_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`BRANCH_ID` AS `BRANCH_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`LAREA_ID` AS `LAREA_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`MTSO_ID` AS `MTSO_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`MTSO_TEAM_ID` AS `MTSO_TEAM_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`VENDOR_ID` AS `VENDOR_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`MME_NAME` AS `MME_NAME`,
    `pemdb1`.`CL_MME_ADV_TPL`.`NET_NAME` AS `NET_NAME`,
    `pemdb1`.`CL_MME_ADV_TPL`.`HOST` AS `HOST`,
    `pemdb1`.`CL_MME_ADV_TPL`.`REALM` AS `REALM`,
    `pemdb1`.`CL_MME_ADV_TPL`.`DFTAPNV4` AS `DFTAPNV4`,
    `pemdb1`.`CL_MME_ADV_TPL`.`DFTAPNV6` AS `DFTAPNV6`,
    `pemdb1`.`CL_MME_ADV_TPL`.`DFTAPNV4V6` AS `DFTAPNV4V6`,
    `pemdb1`.`CL_MME_ADV_TPL`.`N3_CNT` AS `N3_CNT`,
    `pemdb1`.`CL_MME_ADV_TPL`.`DWRRETRY` AS `DWRRETRY`,
    `pemdb1`.`CL_MME_ADV_TPL`.`IWSRETRY` AS `IWSRETRY`,
    `pemdb1`.`CL_MME_ADV_TPL`.`CGCHKTM` AS `CGCHKTM`,
    `pemdb1`.`CL_MME_ADV_TPL`.`CAPA` AS `CAPA`,
    `pemdb1`.`CL_MME_ADV_TPL`.`FEATLIST` AS `FEATLIST`,
    `pemdb1`.`CL_MME_ADV_TPL`.`DFTRFSP` AS `DFTRFSP`,
    `pemdb1`.`CL_MME_ADV_TPL`.`DSCP` AS `DSCP`,
    `pemdb1`.`CL_MME_ADV_TPL`.`USEIMEI` AS `USEIMEI`,
    `pemdb1`.`CL_MME_ADV_TPL`.`PAGEFAIL` AS `PAGEFAIL`,
    `pemdb1`.`CL_MME_ADV_TPL`.`RLB` AS `RLB`,
    `pemdb1`.`CL_MME_ADV_TPL`.`SDBCLR` AS `SDBCLR`,
    `pemdb1`.`CL_MME_ADV_TPL`.`SESSCLR` AS `SESSCLR`,
    `pemdb1`.`CL_MME_ADV_TPL`.`GTPCCLR` AS `GTPCCLR`,
    `pemdb1`.`CL_MME_ADV_TPL`.`VERSION` AS `VERSION`,
