    `pemdb1`.`CL_MME_ADV_TPL`.`SERVICE_AREA` AS `SERVICE_AREA`,
    `pemdb1`.`CL_MME_ADV_TPL`.`UPDATE_DATETIME` AS `UPDATE_DATETIME`,
    `pemdb1`.`CL_MME_ADV_TPL`.`UPDATE_USER_ID` AS `UPDATE_USER_ID`,
    `pemdb1`.`CL_MME_ADV_TPL`.`INSERT_DATE` AS `INSERT_DATE`,
    `pemdb1`.`CL_MME_ADV_TPL`.`UPDATE_DATE` AS `UPDATE_DATE`,
    `pemdb1`.`CL_MME_ADV_TPL`.`OFF_DATE` AS `OFF_DATE`,
