from
    `pemdb1`.`CL_MME_ADV_TPL`;


-- pemdb1.V_CL_NODE_P source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_NODE_P` (`C_TYPE`,
`NODE_TYPE`,
`NODE_ID`,
`NODE_EXP_ID`,
`NODE_KEY_ID`,
`MTSO_ID`,
`MTSO_NAME`) AS
select
    `A`.`C_TYPE` AS `C_TYPE`,
    `A`.`NODE_TYPE` AS `NODE_TYPE`,
    `A`.`NODE_ID` AS `NODE_ID`,
    `A`.`NODE_EXP_ID` AS `NODE_EXP_ID`,
    `A`.`NODE_KEY_ID` AS `NODE_KEY_ID`,
    `A`.`MTSO_ID` AS `MTSO_ID`,
    `B`.`MTSO_NAME` AS `MTSO_NAME`
from
    ((
    select
        'EPC' AS `C_TYPE`,
        'MME' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`V_CL_MME`.`MME_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'MME#')
        or (0 <> lpad(cast(`pemdb1`.`V_CL_MME`.`MME_ID` as unsigned), 2, '0'))) AS `NODE_EXP_ID`,
        ((0 <> 'MME#')
        or (0 <> lpad(cast(`pemdb1`.`V_CL_MME`.`MME_ID` as unsigned), 2, '0'))) AS `NODE_KEY_ID`,
        `pemdb1`.`V_CL_MME`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`V_CL_MME`
union
    select
        'EPC' AS `C_TYPE`,
        'PGW' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`CL_PGW`.`PGW_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'PGW#')
        or (0 <> `ID_DIGITS`(`pemdb1`.`CL_PGW`.`PGW_ID`))) AS `NODE_EXP_ID`,
        ((0 <> 'PGW#')
        or (0 <> `ID_DIGITS`(`pemdb1`.`CL_PGW`.`PGW_ID`))) AS `NODE_KEY_ID`,
        `pemdb1`.`CL_PGW`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`CL_PGW`
    where
        (`pemdb1`.`CL_PGW`.`OPR_STATUS` = 'ACT')
union
    select
        'EPC' AS `C_TYPE`,
        'SGW' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`CL_SGW`.`SGW_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'SGW#')
            or (0 <> `ID_DIGITS`(`pemdb1`.`CL_SGW`.`SGW_ID`))) AS `NODE_EXP_ID`,
        ((0 <> 'SGW#')
            or (0 <> `ID_DIGITS`(`pemdb1`.`CL_SGW`.`SGW_ID`))) AS `NODE_KEY_ID`,
        `pemdb1`.`CL_SGW`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`CL_SGW`
union
    select
        'DNS' AS `C_TYPE`,
        'DNS' AS `NODE_TYPE`,
        lpad(cast(`A`.`DNS_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> `C`.`MTSO_NAME`)
            or (0 <> 'DNS(')
                or (0 <> `B`.`DNS_TYPE_NAME`)
                    or (0 <> ')')) AS `NODE_EXP_ID`,
        ((0 <> 'DNS#')
            or (0 <> lpad(cast(`A`.`DNS_ID` as unsigned), 2, '0'))) AS `NODE_KEY_ID`,
        `A`.`MTSO_ID` AS `MTSO_ID`
    from
        ((`pemdb1`.`CL_DNS` `A`
    join `pemdb1`.`CU_DNS_TYPE_INFO` `B`)
    join `pemdb1`.`CB_MTSO` `C`)
    where
        ((`A`.`DNS_ID` = `B`.`DNS_ID`)
            and (`A`.`MTSO_ID` = `C`.`MTSO_ID`))
union
    select
        'ETC' AS `C_TYPE`,
        'HLR' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`CL_HLRCS`.`HLRCS_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'HLR#')
            or (0 <> lpad(cast(`pemdb1`.`CL_HLRCS`.`HLRCS_ID` as unsigned), 3, '0'))) AS `NODE_EXP_ID`,
        ((0 <> 'HLR#')
            or (0 <> lpad(cast(`pemdb1`.`CL_HLRCS`.`HLRCS_ID` as unsigned), 3, '0'))) AS `NODE_KEY_ID`,
        `pemdb1`.`CL_HLRCS`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`CL_HLRCS`
union
    select
        'ETC' AS `C_TYPE`,
        'AuC' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`CL_AUC`.`AUC_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'AuC#')
            or (0 <> lpad(cast(`pemdb1`.`CL_AUC`.`AUC_ID` as unsigned), 2, '0'))) AS `NODE_EXP_ID`,
        ((0 <> 'AuC#')
            or (0 <> lpad(cast(`pemdb1`.`CL_AUC`.`AUC_ID` as unsigned), 2, '0'))) AS `NODE_KEY_ID`,
        `pemdb1`.`CL_AUC`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`CL_AUC`
union
    select
        'ETC' AS `C_TYPE`,
        'EIR' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`CL_EIR`.`EIR_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'EIR#')
            or (0 <> lpad(cast(`pemdb1`.`CL_EIR`.`EIR_ID` as unsigned), 2, '0'))) AS `NODE_EXP_ID`,
        ((0 <> 'EIR#')
            or (0 <> lpad(cast(`pemdb1`.`CL_EIR`.`EIR_ID` as unsigned), 2, '0'))) AS `NODE_KEY_ID`,
        `pemdb1`.`CL_EIR`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`CL_EIR`
union
    select
        'ETC' AS `C_TYPE`,
        'GLR' AS `NODE_TYPE`,
        lpad(cast(`pemdb1`.`CL_GLR`.`GLR_ID` as unsigned), 4, '0') AS `NODE_ID`,
        ((0 <> 'GLR#')
            or (0 <> lpad(cast(`pemdb1`.`CL_GLR`.`GLR_ID` as unsigned), 2, '0'))) AS `NODE_EXP_ID`,
        ((0 <> 'GLR#')
            or (0 <> lpad(cast(`pemdb1`.`CL_GLR`.`GLR_ID` as unsigned), 2, '0'))) AS `NODE_KEY_ID`,
        `pemdb1`.`CL_GLR`.`MTSO_ID` AS `MTSO_ID`
    from
        `pemdb1`.`CL_GLR`) `A`
left join (
    select
        `pemdb1`.`V_CB_MTSO`.`MTSO_ID` AS `MTSO_ID`,
        `pemdb1`.`V_CB_MTSO`.`MTSO_NAME` AS `MTSO_NAME`
    from
        `pemdb1`.`V_CB_MTSO`
union
    select
        51 AS `51`,
        'SKB' AS `SKB`
union
    select
        61 AS `61`,
        '??' AS `??`
union
    select
        99 AS `99`,
        '??' AS `??`) `B` on
    ((`A`.`MTSO_ID` = `B`.`MTSO_ID`)));


-- pemdb1.V_CL_VLAN source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CL_VLAN` (`MTSO_ID`,
`MTSO_NAME`,
`VLAN_ID`,
`VLAN_INFO`) AS
select
    distinct `pemdb1`.`V_CL_ENB`.`MTSO_ID` AS `mtso_id`,
    `pemdb1`.`V_CL_ENB`.`MTSO_NAME` AS `mtso_name`,
    `pemdb1`.`V_CL_ENB`.`VLAN_ID` AS `vlan_id`,
    `pemdb1`.`V_CL_ENB`.`VLAN_INFO` AS `vlan_info`
from
    `pemdb1`.`V_CL_ENB`
where
    (`pemdb1`.`V_CL_ENB`.`VLAN_INFO` is not null)
order by
    `pemdb1`.`V_CL_ENB`.`MTSO_ID`,
    `pemdb1`.`V_CL_ENB`.`VLAN_ID`;


-- pemdb1.V_CM_CELL_REP_RU_CO source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CM_CELL_REP_RU_CO` (`ENB_ID`,
`SECTOR`,
`CITY_ID`,
`GU_ID`,
`DONG_ID`,
`RU_CUID`,
`LATITUDE`,
`LONGITUDE`,
`FLAG`,
`RU_NAME`,
`PLMN`,
`CO_YN`) AS
select
    `A`.`ENB_ID` AS `ENB_ID`,
    `A`.`SECTOR` AS `SECTOR`,
    `A`.`CITY_ID` AS `CITY_ID`,
    `A`.`GU_ID` AS `GU_ID`,
    `A`.`DONG_ID` AS `DONG_ID`,
    `A`.`RU_CUID` AS `RU_CUID`,
    `A`.`LATITUDE` AS `LATITUDE`,
    `A`.`LONGITUDE` AS `LONGITUDE`,
    `A`.`FLAG` AS `FLAG`,
    `A`.`RU_NAME` AS `RU_NAME`,
    '45005' AS `PLMN`,
    (case
        when ((`A`.`ENB_ID` = `B`.`ENB_ID`)
        and (`A`.`SECTOR` = `B`.`SECTOR`)) then 'Y'
        else 'N'
    end) AS `CO_YN`
from
    (`pemdb1`.`CM_CELL_REP_RU` `A`
left join (
    select
        `pemdb1`.`CM_CELL_REP_RU_CO`.`ENB_ID` AS `ENB_ID`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`SECTOR` AS `SECTOR`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`CITY_ID` AS `CITY_ID`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`GU_ID` AS `GU_ID`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`DONG_ID` AS `DONG_ID`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`RU_CUID` AS `RU_CUID`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`LATITUDE` AS `LATITUDE`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`LONGITUDE` AS `LONGITUDE`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`FLAG` AS `FLAG`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`RU_NAME` AS `RU_NAME`,
        `pemdb1`.`CM_CELL_REP_RU_CO`.`PLMN` AS `PLMN`
    from
        `pemdb1`.`CM_CELL_REP_RU_CO`
    where
        (`pemdb1`.`CM_CELL_REP_RU_CO`.`PLMN` = '45005')) `B` on
    (((`A`.`ENB_ID` = `B`.`ENB_ID`) and (`A`.`SECTOR` = `B`.`SECTOR`))))
union all
select
    `A`.`ENB_ID` AS `ENB_ID`,
    `A`.`SECTOR` AS `SECTOR`,
    `A`.`CITY_ID` AS `CITY_ID`,
    `A`.`GU_ID` AS `GU_ID`,
    `A`.`DONG_ID` AS `DONG_ID`,
    `A`.`RU_CUID` AS `RU_CUID`,
    `A`.`LATITUDE` AS `LATITUDE`,
    `A`.`LONGITUDE` AS `LONGITUDE`,
    `A`.`FLAG` AS `FLAG`,
    `A`.`RU_NAME` AS `RU_NAME`,
    `A`.`PLMN` AS `PLMN`,
    'Y' AS `CO_YN`
from
    `pemdb1`.`CM_CELL_REP_RU_CO` `A`
where
    (`A`.`PLMN` <> '45005');


-- pemdb1.V_CM_CELL_REP_RU_ENC_CO source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CM_CELL_REP_RU_ENC_CO` (`ENB_ID`,
