    `A`.`CITY_ID` AS `CITY_ID`,
    `A`.`GU_ID` AS `GU_ID`,
    `A`.`DONG_ID` AS `DONG_ID`,
    `A`.`RU_CUID` AS `RU_CUID`,
    `A`.`LATITUDE` AS `LATITUDE`,
    `A`.`LONGITUDE` AS `LONGITUDE`,
    `A`.`FLAG` AS `FLAG`,
    `A`.`RU_NAME` AS `RU_NAME`,
    `A`.`DECODE` AS `DECODE`,
    `A`.`PLMN` AS `PLMN`,
    'Y' AS `CO_YN`
from
    `pemdb1`.`CM_CELL_REP_RU_ENC_CO` `A`
where
    (`A`.`PLMN` <> '45005');


-- pemdb1.V_CM_CELL_REP_RU_ORGAN source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_CM_CELL_REP_RU_ORGAN` (`ENB_ID`,
`CELL_ID`,
`CITY_ID`,
`GU_ID`,
`DONG_ID`,
`BRANCH_ID`,
`COMPANY_ID`,
`TEAM_ID`,
`PART_ID`,
`EMS_ID`) AS
select
    `a`.`ENB_ID` AS `enb_id`,
    `a`.`SECTOR` AS `CELL_ID`,
    ifnull(`a`.`CITY_ID`, '0') AS `IFNULL(a.city_id,'0')`,
    ifnull(`a`.`GU_ID`, '0') AS `IFNULL(a.gu_id,'0')`,
    ifnull(`a`.`DONG_ID`, '0') AS `IFNULL(a.dong_id,'0')`,
    ifnull(`b`.`BRANCH_ID`, '0') AS `IFNULL(b.branch_id,'0')`,
    ifnull(`b`.`COMPANY_ID`, '0') AS `IFNULL(b.company_id,'0')`,
    ifnull(`b`.`OPTEAM_ID`, '0') AS `IFNULL(b.opteam_id,'0')`,
    ifnull(`b`.`PART_ID`, '0') AS `IFNULL(b.part_id,'0')`,
    ifnull(`b`.`EMS_ID`, '0') AS `IFNULL( b.ems_id ,'0')`
from
    (`pemdb1`.`CM_CELL_REP_RU` `a`
left join `pemdb1`.`CL_ENB` `b` on
    ((`a`.`ENB_ID` = `b`.`ENB_ID`)));


-- pemdb1.V_PM_APP_LAST_TIME_NEW source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_PM_APP_LAST_TIME_NEW` (`EVENT_TIME`) AS
select
    min(`A`.`EVENT_TIME`) AS `EVENT_TIME`
from
    (
    select
        min(`pemdb1`.`PM_STAT_STATUS`.`EVENT_TIME`) AS `EVENT_TIME`
    from
        `pemdb1`.`PM_STAT_STATUS`
    where
        ((1 = 1)
            and (`pemdb1`.`PM_STAT_STATUS`.`STAT_TYPE` = '1M')
                and (`pemdb1`.`PM_STAT_STATUS`.`REPORT_NAME` in ('PM_APP_ATT_1M', 'PM_APP_TTT_1M', 'PM_APP_THR_1M', 'PM_APP_TCP_1M', 'PM_APP_HTTP_1M', ' PM_DNS_1M', 'PM_APP_TTT_TOT_1M', 'PM_APP_ATT_TOT_1M', 'PM_DNS_KPI_1M', 'PM_APP_TTT_UNIQ_IMSI_1M', 'APP_ALARM'))
                    and (`pemdb1`.`PM_STAT_STATUS`.`EVENT_TIME` is not null))) `A`;


