CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_PM_CEI5M_LAST_TIME` (`EVENT_TIME`) AS
select
    max(`A`.`EVENT_TIME`) AS `EVENT_TIME`
from
    `pemdb1`.`PM_CEI_PGW_5M` `A`;


-- pemdb1.V_PM_NWTOPN_LAST_TIME source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_PM_NWTOPN_LAST_TIME` (`EVENT_TIME`) AS
