    `pemdb1`.`PM_ENB_TOTAL_KPI_1M` `A`;


-- pemdb1.V_PM_TOPOLOGY_LAST_TIME source

CREATE OR REPLACE
ALGORITHM = UNDEFINED VIEW `pemdb1`.`V_PM_TOPOLOGY_LAST_TIME` (`EVENT_TIME`) AS
select
    max(`B`.`EVENT_TIME`) AS `MAX(B.EVENT_TIME)`
from
    (
    select
        min(`A`.`EVENT_TIME`) AS `EVENT_TIME`
    from
        (
        select
            `pemdb1`.`PM_STAT_STATUS`.`STAT_TYPE` AS `STAT_TYPE`,
            `pemdb1`.`PM_STAT_STATUS`.`EVENT_TIME` AS `EVENT_TIME`,
            `pemdb1`.`PM_STAT_STATUS`.`UPDATE_TIME` AS `UPDATE_TIME`,
            `pemdb1`.`PM_STAT_STATUS`.`REPORT_NAME` AS `REPORT_NAME`
        from
            `pemdb1`.`PM_STAT_STATUS`) `A`
    where
        ((1 = 1)
            and (`A`.`STAT_TYPE` = '1M')
                and (`A`.`REPORT_NAME` in ('PM_EPC_KPI_1M', 'PM_ENB_KPI_1M', 'PM_LINK_EPC_KPI_1M', 'PM_LINK_ENB_KPI_1M', 'NW_ALARM')))) `B`;